'use strict';
window.CobaltMap465={
 t:(z,e)=>I18n.language==='en'?e:z,sequence:0,
 install(){if(this.installed)return;this.installed=true;CobaltStockUI.map=()=>this.open();CobaltStockUI.selectLocation=id=>this.select(id);},
 link(path,values={}){const q=new URLSearchParams(location.search);for(const k of ['page','location_id','zone_id','bag','production_batch'])q.delete(k);for(const[k,v]of Object.entries(values))v==null||v===''?q.delete(k):q.set(k,v);return path+(q.size?'?'+q:'');},
 state(l){if(!l.active||!l.zone_active)return 'DISABLED';if(!l.bags)return l.occupied_by?'VERIFY':'EMPTY';if(l.loading_occupied_bags>0){if(['LOADING','REVIEW_PENDING','LOADED','DEPARTED'].includes(l.lifecycle_state))return 'LOADING';if(['OUTBOUND_PENDING','LOGISTICS_APPROVED','OUTBOUND_CORRECTION'].includes(l.lifecycle_state))return 'OUTBOUND_REVIEW';return 'MATCHED';}if(l.intake_status==='PRODUCTION_PENDING')return 'PRODUCTION_REVIEW';if(l.work_status==='PENDING_COMPLETION_REVIEW'||l.intake_status==='SITE_PENDING'||l.amendment_status==='PENDING')return 'SITE_REVIEW';return l.work_status==='COMPLETED'&&l.intake_status==='RECEIVED'?'READY':'PREPARING';},
 states:['PREPARING','SITE_REVIEW','PRODUCTION_REVIEW','READY','MATCHED','LOADING','OUTBOUND_REVIEW','EMPTY','VERIFY','DISABLED'],
 stateText(s){return this.t(...({PREPARING:['备货作业中','Preparation'],SITE_REVIEW:['待现场主管审核','Site Review'],PRODUCTION_REVIEW:['待生产经理确认入库','Production Receipt Review'],READY:['已入库可匹配','Received / Ready'],MATCHED:['已匹配锁定','Matched / Locked'],LOADING:['装车办理中','Loading'],OUTBOUND_REVIEW:['出库审批中','Outbound Review'],VERIFY:['占用待核实','Reservation to Verify'],EMPTY:['空货位','Empty'],DISABLED:['已停用','Disabled'],OCCUPIED:['在位库存','Stock at Location'],LOCKED:['匹配锁定','Loading Plan Locked']}[s]||[s,s]));},
 async open(){const seq=++this.sequence,q=new URLSearchParams(location.search);if(!q.get('warehouse_id')){const o=await API.request('/cobalt/options'),w=o.warehouses.find(w=>!q.get('project_id')||w.project_id===q.get('project_id'));if(w){q.set('project_id',w.project_id);q.set('warehouse_id',w.id);history.replaceState(history.state,'','/stock-map?'+q);}}
  const [d,filters]=await Promise.all([API.request('/cobalt/stock/map?'+q),CobaltStockUI.filters()]);if(seq!==this.sequence||ProductContext.isCopper()||location.pathname!=='/stock-map')return;this.data=d;CobaltStockUI.mapData=d;const t=this.t,counts={all:d.locations.length,occupied:d.locations.filter(l=>l.bags>0).length};
  CobaltUI.page(t('氢氧化钴库存地图','Cobalt Stock Map'),'<div class="co-stock-page map465">'+filters+'<section class="map465-stats">'+[[t('已配置货位','Configured Locations'),counts.all],[t('有实物货位','Occupied Locations'),counts.occupied],[t('当前库存袋数','Stock Bags'),d.summary.bags],[t('未定位袋数','Unlocated Bags'),d.summary.unlocated_bags]].map(([label,n])=>'<article><span>'+label+'</span><strong>'+n+'</strong></article>').join('')+'</section><div class="map465-actions"><div><a class="button secondary" href="'+esc(this.link('/inventory'))+'">'+t('查询库存明细','View Stock')+'</a><a class="button secondary" href="'+esc(this.link('/inventory',{unlocated:'1'}))+'">'+t('未定位库存','Unlocated Stock')+' · '+d.summary.unlocated_bags+'</a>'+(CobaltStockUI.can('co:location-manage')?'<a class="button primary" href="#co-layout-config">＋ '+t('配置库区与货位','Configure Zones and Locations')+'</a>':'')+'</div><span>'+t('读取时点：','Snapshot: ')+BusinessTime.display(d.snapshot_at)+'</span></div><div class="map465-grid"><section id="co-map-stage" class="map465-stage"><div class="co-map-toolbar" data-work-view><button id="co-map-fullscreen" type="button" class="button secondary">'+t('全屏查看','Fullscreen')+'</button><button id="co-map-in" type="button" class="button secondary" aria-label="'+t('放大','Zoom In')+'">＋</button><button id="co-map-out" type="button" class="button secondary" aria-label="'+t('缩小','Zoom Out')+'">−</button><button id="co-map-fit" type="button" class="button secondary">'+t('完整地图','Fit Map')+'</button><label>'+t('缩放','Zoom')+'<input id="co-map-zoom" type="range" min="1" max="8" step=".01" value="1"></label><span id="co-map-scale">100%</span></div><div class="map465-legend">'+this.states.filter(s=>s!=='VERIFY').map(k=>'<span class="map465-key map465-tone-'+k.toLowerCase()+'"><i></i>'+this.stateText(k)+'</span>').join('')+'</div><div id="co-map-canvas" tabindex="0"></div><div id="co-map-labels" class="co-map-labels"></div></section><aside id="co-map-detail" class="map465-detail" hidden aria-live="polite"><div class="map465-prompt"><span aria-hidden="true">⌖</span><h3>'+t('货位详情','Location Preview')+'</h3><p>'+t('选择地图货位或下方货位卡片，查看在位批次、袋数与重量。','Select a location or its card to see its current batch, bags and weights.')+'</p></div></aside></div><section class="map465-locations"><header><h3>'+t('货位明细','Location Directory')+'</h3><label>'+t('状态','State')+'<select id="map465-state" data-work-view><option value="">'+t('全部','All')+'</option>'+this.states.map(k=>'<option value="'+k+'">'+this.stateText(k)+'</option>').join('')+'</select></label></header><div id="map465-location-list"></div></section>'+(CobaltStockUI.can('co:location-manage')?CobaltStockUI.configForm(d):'')+'<p id="co-stock-error" class="error" role="alert"></p></div>');
  CobaltStockUI.bindFilters();if(!window.CobaltMapSite?.draw(d))CobaltStockUI.draw(d);document.getElementById('co-map-labels').hidden=true;for(const l of d.locations){const g=document.querySelector('[data-co-location="'+l.id+'"]');if(g){g.dataset.stockState=this.state(l);const count=g.querySelector('text:last-child');if(count)count.textContent=d.site_plan?(Number(l.width)<100?l.code.split('-').pop():l.code.replace(/^CO-/,'')):l.bags+' '+t('袋','Bags')+' · '+t('匹配','Matched')+' '+l.matched_bags;g.querySelector('title').textContent=l.code+' · '+(l.preparation_batch_no||this.stateText(this.state(l)))+' · '+this.stateText(this.state(l));g.classList.toggle('map465-selected',this.selected===l.id);}}
  if(!d.locations.length&&!d.site_plan)document.getElementById('co-map-canvas').innerHTML='<div class="map465-empty"><span aria-hidden="true">⌖</span><h3>'+t('尚未配置现场货位','Site Locations Are Not Configured')+'</h3><p>'+t('当前库存和未定位数量如实显示。配置库区与固定货位后，地图将自动关联真实库存；历史图纸批次不会导入为当前库存。','Current stock and unlocated quantities are shown as recorded. Configure confirmed zones and fixed locations to connect the map to live stock. Historical diagram batches are not imported as current stock.')+'</p></div>';
  document.getElementById('co-map-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.map465-grid').requestFullscreen();}catch(e){document.getElementById('co-stock-error').textContent=CobaltStockUI.error(e);}};document.getElementById('map465-state').onchange=()=>this.cards();this.cards();if(q.get('location_id')&&d.locations.some(l=>l.id===q.get('location_id')))this.selected=q.get('location_id');else if(q.get('preparation_id'))this.selected=d.locations.find(l=>l.occupied_by===q.get('preparation_id'))?.id;await CobaltStockUI.bindConfig(d);ProductContext.dirty=false;if(this.selected&&d.locations.some(l=>l.id===this.selected))await this.select(this.selected);
 },
 cards(){const wanted=document.getElementById('map465-state').value;for(const l of this.data.locations)document.querySelector('[data-co-location="'+l.id+'"]')?.classList.toggle('map465-state-dimmed',!!wanted&&this.state(l)!==wanted);const list=document.getElementById('map465-location-list'),locations=this.data.locations.filter(l=>(l.bags>0||l.occupied_by)&&(!wanted||this.state(l)===wanted));list.innerHTML=locations.map(l=>'<button class="map465-location-card" type="button" data-map465-location="'+l.id+'" data-state="'+this.state(l)+'"><header><strong data-no-i18n>'+esc(l.code)+'</strong><span>'+this.stateText(this.state(l))+'</span></header><p data-no-i18n>'+esc(l.preparation_batch_no||this.t('暂无在位批次','No Batch at Location'))+'</p><footer><span>'+esc(I18n.language==='en'?l.zone_name_en:l.zone_name)+'</span><b>'+l.bags+' '+this.t('袋','Bags')+'</b></footer></button>').join('')||'<p class="map465-muted">'+this.t('当前范围暂无符合条件的货位','No locations match this scope')+'</p>';for(const b of list.querySelectorAll('button'))b.onclick=()=>this.select(b.dataset.map465Location);},
 async select(id){const l=this.data?.locations.find(l=>l.id===id),box=document.getElementById('co-map-detail');if(!l||!box)return;box.hidden=!(l.bags>0||l.occupied_by);if(box.hidden){this.selection=(this.selection||0)+1;this.selected=null;CobaltStockUI.selectedLocation=null;box.replaceChildren();for(const g of document.querySelectorAll('[data-co-location]'))g.classList.remove('map465-selected');return;}this.selected=id;CobaltStockUI.selectedLocation=id;const token=this.selection=(this.selection||0)+1,signature=ProductContext.code+'|'+location.pathname+location.search,t=this.t;box.innerHTML='<h3 data-no-i18n>'+esc(l.code)+'</h3><span class="map465-state" data-state="'+this.state(l)+'">'+this.stateText(this.state(l))+'</span><p class="map465-zone">'+esc(I18n.language==='en'?l.zone_name_en:l.zone_name)+'</p><h4 data-no-i18n>'+esc(l.preparation_batch_no||t('暂无在位批次','No Batch at Location'))+'</h4><div class="map465-detail-body">'+t('正在读取真实库存…','Reading live stock…')+'</div>';for(const g of document.querySelectorAll('[data-co-location]'))g.classList.toggle('map465-selected',g.dataset.coLocation===id);
  if(!l.occupied_by||!l.bags){box.querySelector('.map465-detail-body').innerHTML='<p class="map465-muted">'+t(l.occupied_by?'暂无在位实物，占用关系需现场核实。':'当前货位没有在位实物。',l.occupied_by?'No physical stock is recorded here. Verify the reservation on site.':'No physical stock is recorded here.')+'</p>';return;}
  if(l.intake_status&&l.intake_status!=='RECEIVED'){box.querySelector('.map465-detail-body').innerHTML='<dl><div><dt>'+t('已定位袋数','Located Bags')+'</dt><dd>'+l.bags+'</dd></div><div><dt>'+t('入库状态','Receipt Status')+'</dt><dd>'+t('待最终确认入库','Awaiting Final Receipt Confirmation')+'</dd></div></dl><div class="map465-detail-links"><a class="button primary" href="/receipts/'+l.occupied_by+'/work">'+t('查看备货作业','View Preparation Work')+'</a></div>';return;}
  try{const d=await API.request('/cobalt/stock/batches/'+l.occupied_by+'?'+new URLSearchParams({location_id:id}));if(this.selection!==token||signature!==ProductContext.code+'|'+location.pathname+location.search||!box.isConnected)return;const b=d.batch;if(!b){box.querySelector('.map465-detail-body').innerHTML='<p>'+t('该货位库存已变化，请重新查询。','Stock changed. Search again.')+'</p>';return;}box.querySelector('.map465-detail-body').innerHTML='<dl>'+[[t('在位袋数','Bags Here'),d.total],[t('已确认净重（吨）','Confirmed Net (MT)'),b.actual_net_mt==null?t('未知','Unknown'):Tonnes.format(b.actual_net_mt)],[t('未确认重量袋数','Unconfirmed Weight Bags'),b.unconfirmed_bags],[t('备货状态','Work Status'),CobaltStockUI.status(b.status)]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><div class="map465-detail-links"><a class="button primary" href="'+esc(this.link('/inventory/'+l.occupied_by,{location_id:id,unlocated:null}))+'">'+t(CobaltStockUI.can('co:locate')?'查看明细 / 调整货位':'查看袋级明细',CobaltStockUI.can('co:locate')?'View Bags / Relocate':'View Bag Details')+'</a>'+(CobaltStockUI.can('co:read')?'<a class="button secondary" href="/receipts/'+l.occupied_by+'/work">'+t('查看备货作业','View Preparation Work')+'</a>':'')+'</div><h5>'+t('在位捆袋预览','Bags at This Location')+'</h5><div class="map465-bags">'+d.items.slice(0,8).map(x=>'<article><strong data-no-i18n>'+esc(x.bag_no)+'</strong><span>'+t('净重：','Net: ')+(x.actual_net_kg==null?t('未确认','Unconfirmed'):esc(x.actual_net_kg)+' kg')+'</span><span>'+t('铅封：','Seal: ')+esc(x.seal_no||'—')+'</span></article>').join('')+'</div>'+(d.total>8?'<p class="map465-muted">'+t('其余实物请进入袋级明细查看。','Open bag details to see the remaining stock.')+'</p>':'');if(l.temporary)window.CobaltMapSite?.detail(l);}catch(e){if(this.selection===token&&box.isConnected){box.querySelector('.map465-detail-body').textContent=CobaltStockUI.error(e);}}
 }
};
